//! 2026-10-17: The `runtime` lever group: the `runtime.*` levers a `met` process reads at run time.
//!
//! Owner: settings.
//! Invariants: rows in env-name order.

lever_group! {
    /// 2026-10-17: The `runtime` group, resolved by `crate::resolve()`.
    pub struct RuntimeSettings { group: "runtime", class: Runtime }
    bisect_no_mix: Switch = "off", None, "METRALE_BISECT_NO_MIX", "crates/server/src/scheduler/levers.rs", "`METRALE_BISECT_NO_MIX=1|true`: never fuse prefill with decode. `1` or `true` turns it on.";
    comm_poll: Text = "200:50", None, "METRALE_COMM_POLL", "crates/comm/src/collective_wait.rs", "`<spin_us>:<sleep_us>`: how an NCCL broadcast wait (the multi-rank command words) pauses between `cuStreamQuery` polls: yield for `spin_us`, then sleep `sleep_us` per poll. `0:1000` is the fixed 1 ms sleep used before 2026-10-09 (the A/B control); a long `spin_us` (e.g. `100000:50`) keeps a worker spinning through its decode step. Host timing only: tokens are unchanged.";
    conc_hsd: Switch = "off", None, "METRALE_CONC_HSD", "crates/model-layers/src/layers/ops/model_levers_resolve.rs", "Sets `conc_hsd` (read in `crates/model-layers/src/layers/ops/model_levers_resolve.rs`). `1` or `true` turns it on.";
    cublas_scale_layout: Text = "unset", None, "METRALE_CUBLAS_SCALE_LAYOUT", "crates/model-layers/src/layers/ops/dispatch_proj.rs", "`METRALE_CUBLAS_SCALE_LAYOUT` — which VEC128 activation-scale layout the cuBLASLt block-scaled arm feeds the library.";
    ds41_arena_device: Switch = "on", None, "METRALE_DS41_ARENA_DEVICE", "crates/model-arch/src/weight_loader/deepseek_v41/load_layers.rs", "The slots in DEVICE memory behind a page-locked staging ring (the expert GEMV reads device memory at 215 GB/s and the pinned arena at 176, same kernel, same counters: 3.2 ms of a 44 ms step,. `0` turns it off.";
    ds41_device_route: Switch = "off", None, "METRALE_DS41_DEVICE_ROUTE", "crates/model-arch/src/moe_v41/device_route.rs", "The single-token routing on the device (`METRALE_DS41_DEVICE_ROUTE=1`). `1` turns it on.";
    dsa_select_rows: Switch = "on", None, "METRALE_DSA_SELECT_ROWS", "crates/model-arch/src/glm5next_dsa/layer/workspace.rs", "ON by default; `METRALE_DSA_SELECT_ROWS=0` is the kill-switch back to per-row selection. `0` turns it off.";
    dspark_anchor_bias: Switch = "on", None, "METRALE_DSPARK_ANCHOR_BIAS", "crates/model-arch/src/dflash_head/levers.rs", "Ships ON; `METRALE_DSPARK_ANCHOR_BIAS=0` exempts it. `0` turns it off.";
    dspark_conf_tau: Text = "unset", None, "METRALE_DSPARK_CONF_TAU", "crates/model-arch/src/dflash_head/levers.rs", "`METRALE_DSPARK_CONF_TAU=<t>` — sigmoid-space acceptance threshold for the confidence head.";
    dspark_shift: Text = "unset", None, "METRALE_DSPARK_SHIFT", "crates/model-arch/src/dflash_head/levers.rs", "`METRALE_DSPARK_SHIFT=1|0` forces the SpecForge shifted-row convention on or off; unset (`None`) defers to the drafter config.";
    ep_device_argmax: Switch = "off", None, "METRALE_EP_DEVICE_ARGMAX", "crates/model-engine/src/model/device_argmax.rs", "With the asynchronous router, the v3 wire and a vocab-sharded BF16 LM head on a multi-rank serve (GLM-5.3): a one-row decode step whose readback is the device argmax ends with each rank keying its head slice and resolving the token from a 16-byte key exchange, instead of all-reducing the logits row and running the argmax on rank 0. Tokens are unchanged; the logits of such a step are not gathered. `1` turns it on.";
    ep_device_feed: Switch = "off", None, "METRALE_EP_DEVICE_FEED", "crates/model-engine/src/model/trait_impl/decode_fed_ep.rs", "With `--scheduler-config async` on a multi-rank serve (`METRALE_EP_PROTOCOL=v2`) whose layers capture their decode with the communicator (GLM-5.3): rank 0 runs a single-row decode step ahead of its host, fed from the previous step's device argmax, and the token reaches the worker ranks by a device broadcast (`EP_CMD_DECODE_FED`). Tokens are unchanged. `1` turns it on.";
    ep_k2_fused: Switch = "off", None, "METRALE_EP_K2_FUSED", "crates/model-layers/src/speculative/k2_wire.rs", "On a multi-rank serve with `METRALE_EP_PROTOCOL=v3` and a sharded MTP drafter: a K=2 verify step announces the verify and both tokens in one v3 block and sends one verdict that also starts the workers' propose, two broadcasts per step instead of nine to eleven. Tokens are unchanged. Refused at startup on another wire. Every rank must use the same value. `1` turns it on.";
    ep_mtp_batch_verify: Switch = "off", None, "METRALE_EP_MTP_BATCH_VERIFY", "crates/model-layers/src/speculative/knobs.rs", "`1`: on a multi-rank serve, MTP sequences with drafts verify as one batched forward (the batched DFlash verify's `EP_CMD_VERIFY_BATCH` wire) when they share one k, instead of one K-row verify per sequence; each sequence then proposes alone. Rank 0 decides it; the workers follow.";
    ep_protocol: Text = "unset", None, "METRALE_EP_PROTOCOL", "crates/model-layers/src/ep_wire.rs", "The multi-rank command wire: `v2` sends a slot word before every command word; `v3` sends that pair as one 12-byte block (`[slot, cmd, arg]`) in one broadcast, one fewer ring round trip per decode step; anything else is v1. Every rank must use the same value.";
    expert_peer: Text = "unset", None, "METRALE_EXPERT_PEER", "crates/storage/src/links.rs", "* `rdma` — connect to `$METRALE_EXPERT_PEER` over TWO-SIDED TCP.";
    gguf_force_cpu: Switch = "off", None, "METRALE_GGUF_FORCE_CPU", "crates/model-weights/src/weights/gguf.rs", "Read in `crates/model-weights/src/weights/gguf.rs`. `1` turns it on.";
    high_speed_swap_replace: Presence = "off", None, "METRALE_HIGH_SPEED_SWAP_REPLACE", "crates/server/src/scheduler/levers.rs", "Read in `crates/server/src/scheduler/levers.rs`. Any value turns it on, `0` included.";
    kv_paging: Text = "unset", None, "METRALE_KV_PAGING", "crates/storage/src/links.rs", "The KV-paging selection seam: env-driven choice between the raw one-sided `RdmaKvBackend` (flag OFF) and the peer-paging `KvPagingBackend` (`METRALE_KV_PAGING=1`).";
    kv_paging_arena_gb: Text = "unset", None, "METRALE_KV_PAGING_ARENA_GB", "crates/storage/src/links.rs", "KV-paging arena size in GiB; required when METRALE_KV_PAGING=1.";
    main_stream_high_priority: Switch = "off", None, "METRALE_MAIN_STREAM_HIGH_PRIORITY", "crates/gpu-runtime/src/cuda_host.rs", "Create the process CUDA stream at the context's greatest priority; side streams keep the least, so a side-stream SSM rollback copy no longer holds the process stream's kernels and graphs. `1` turns it on.";
    main_stream_under_greatest: Switch = "off", None, "METRALE_MAIN_STREAM_UNDER_GREATEST", "crates/gpu-runtime/src/cuda_host.rs", "With METRALE_MAIN_STREAM_HIGH_PRIORITY=1, `1` creates the process stream one priority level under the greatest (still above the side streams' least), so a stream made at the greatest (the GLM SP comm stream) has its blocks dispatched strictly ahead of the process stream's instead of tying with them. Unset or `0` keeps the greatest; another value, `1` without METRALE_MAIN_STREAM_HIGH_PRIORITY=1, or a range with no level between, fails the CUDA host's creation.";
    max_body_bytes: Int = "unset", None, "METRALE_MAX_BODY_BYTES", "crates/server/src/main_modules/serve_router.rs", "Default 32 MB covers typical multi-image and long-prompt requests; raise via `METRALE_MAX_BODY_BYTES` (in bytes) for unusual deployments.";
    nccl_host_hoist: Switch = "off", None, "METRALE_NCCL_HOST_HOIST", "crates/gpu-runtime/src/cuda_backend/graph_hoist_cu.rs", "Before a captured CUDA graph is instantiated, chain its NCCL host-callback nodes on each other instead of on the kernels that produce the collectives' inputs, handing their dependencies to their dependents, so each proxy upload runs ahead and a collective waits only for its producer. `1` turns it on.";
    no_hw_precheck: Text = "unset", None, "METRALE_NO_HW_PRECHECK", "crates/host-probe/src/levers.rs", "Env var that suppresses refusal.";
    no_k64_n64: Presence = "off", None, "METRALE_NO_K64_N64", "crates/model-layers/src/layers/mod.rs", "`KernelHandle(0)` when the kernel is absent or the presence kill switch `METRALE_NO_K64_N64` is set (`=0` is NOT \"off\"). Any value turns it on, `0` included.";
    no_k64_pipeline3: Presence = "off", None, "METRALE_NO_K64_PIPELINE3", "crates/model-layers/src/layers/mod.rs", "**ON by default**; `METRALE_NO_K64_PIPELINE3` (presence — `=0` is NOT \"off\") falls back to the 2-stage parent. Any value turns it on, `0` included.";
    no_mapped_argmax: Switch = "off", None, "METRALE_NO_MAPPED_ARGMAX", "crates/model-engine/src/model/trait_impl/verify_e/mapped_argmax.rs", "Kill switch METRALE_NO_MAPPED_ARGMAX=1 restores scratch + on-stream copy. `1` turns it on.";
    prefill_zero_rows: Switch = "off", None, "METRALE_PREFILL_ZERO_ROWS", "crates/model-engine/src/model/prefill_zero.rs", "`1`: with a communicator (TP/EP), a prefill chunk zeroes the arena rows it touches (`BufferArena::zero_all_rows` at the chunk length rounded up to 16) instead of the whole max-token-sized arena every chunk (2.66 GB, 14 ms of GPU time per chunk at 8208 arena tokens on GLM-5.3, whatever the prompt length). Unset or `0` keeps the whole-arena zero.";
    python: Text = "unset", None, "METRALE_PYTHON", "crates/host-probe/src/levers.rs", "`METRALE_PYTHON` overrides the search — the box may keep the usable interpreter off PATH, and pointing at it must not require a PATH edit.";
    qsa_disable: Switch = "off", None, "METRALE_QSA_DISABLE", "crates/model-arch/src/weight_loader/qwen4_exp/aux_sites.rs", "`METRALE_QSA_DISABLE=1` skips (decode then runs DENSE past the budget, which is NOT the reference model); layers without the tensor are silently non-QSA. `1` turns it on.";
    qsa_score_scalar: Switch = "off", None, "METRALE_QSA_SCORE_SCALAR", "crates/model-layers/src/layers/qsa_select.rs", "METRALE_QSA_SCORE_SCALAR=1 forces the original. `1` turns it on.";
    redzone: Int = "unset", None, "METRALE_REDZONE", "crates/gpu-runtime/src/cuda_backend/redzone.rs", "`METRALE_REDZONE=<bytes>` — guard-band size, 0 (default) disables.";
    redzone_every: Int = "unset", None, "METRALE_REDZONE_EVERY", "crates/model-engine/src/model/trait_impl/decode_a_redzone.rs", "`METRALE_REDZONE_EVERY=<n>` — scan the A55 guard bands every `n`-th decode step. 0 disables the scan while leaving the pads in place (which is the configuration the READ experiment wants: pads...";
    redzone_fill: Int = "unset", None, "METRALE_REDZONE_FILL", "crates/gpu-runtime/src/cuda_backend/redzone.rs", "`METRALE_REDZONE_FILL=<decimal byte>` — the poison value, default `0xEE`.";
    redzone_min_idx: Int = "unset", None, "METRALE_REDZONE_MIN_IDX", "crates/gpu-runtime/src/cuda_backend/redzone.rs", "`METRALE_REDZONE_MIN_IDX=<n>` — pad only allocations whose creation index is `>= n`.";
    snap_evict_alpha: Float = "unset", None, "METRALE_SNAP_EVICT_ALPHA", "crates/cache/src/radix_tree/snapshot.rs", "Default flip requires its own measured A/B: METRALE_SNAP_EVICT_ALPHA.";
    snap_evict_legacy: Presence = "off", None, "METRALE_SNAP_EVICT_LEGACY", "crates/cache/src/radix_tree/snapshot.rs", "SESSION-AWARE eviction (default ON; METRALE_SNAP_EVICT_LEGACY=1 → old per-entry). Any value turns it on, `0` included.";
    softcap_override: Float = "unset", None, "METRALE_SOFTCAP_OVERRIDE", "crates/config/src/legacy_env.rs", "Override softcap via env for A/B testing (llama.cpp #21390: 25.0 fixes creative diversity collapse for NVFP4 Gemma-4 at BF16 precision).";
    sparse_v_threshold: Text = "unset", None, "METRALE_SPARSE_V_THRESHOLD", "crates/model-layers/src/forward/qwen3_5/full_attention.rs", "METRALE_SPARSE_V_THRESHOLD overrides the default 1e-3 from the attention-gated dequant work.";
    ssm_decode_nvme_dir: Path = "unset", None, "METRALE_SSM_DECODE_NVME_DIR", "crates/model-engine/src/model/ssm_tier/selectors.rs", "Selection (`METRALE_SSM_DECODE_TIER`): - `nvme` + `METRALE_SSM_DECODE_NVME_DIR=<dir>` → [`FileSnapshotArena`] behind [`ArenaSnapshotStore`], provably sized ≥ `min_slots`. - `peer` +...";
    ssm_decode_rdma_tier: Text = "unset", None, "METRALE_SSM_DECODE_RDMA_TIER", "crates/model-engine/src/model/ssm_tier/selectors.rs", "Selection (`METRALE_SSM_DECODE_TIER`): - `nvme` + `METRALE_SSM_DECODE_NVME_DIR=<dir>` → [`FileSnapshotArena`] behind [`ArenaSnapshotStore`], provably sized ≥ `min_slots`. - `peer` +...";
    stream_send_deadline_ms: Text = "unset", None, "METRALE_STREAM_SEND_DEADLINE_MS", "crates/server/src/scheduler/run_io.rs", "Default 5000 ms; override `METRALE_STREAM_SEND_DEADLINE_MS` (strict integer).";
    strip_reasoning_history: Switch = "off", None, "METRALE_STRIP_REASONING_HISTORY", "crates/server/src/api/chat/msg_entry.rs", "Wave 3 (2026-05-26): `METRALE_STRIP_REASONING_HISTORY=1` drops historical reasoning_content entirely. `1` or `true` turns it on.";
}
